<template><section class="keyboard-registration" aria-label="맥 키보드 두 개"><h3>키보드 두 개 · 맥 전용</h3><p>각자 방향키 · ↑ 회전 · Space 낙하 · C 홀드 · 아이템 V/B/N 또는 1/2/3</p><div class="registration-tools"><button v-if="!status.enabled" @click="emit('command','enable')">장치별 키보드 사용</button><button v-else @click="emit('command','disable')">한 키보드 조작으로 전환</button><button v-if="!status.permission" @click="emit('command','settings')">입력 모니터링 설정 열기</button></div><div v-for="player in [0,1]" :key="player" class="registration-seat"><span><strong>{{ player+1 }}P</strong><small>{{ name(player) }}</small></span><div><select :aria-label="`${player+1}P 연결된 키보드 선택`" :value="status.seats[player]||''" @change="selectDevice(player,$event)"><option value="" disabled>키보드 직접 선택</option><option v-for="device in status.devices" :key="device.id" :value="device.id" :disabled="status.seats[1-player]===device.id">{{ device.name }}</option></select><button @click="emit('command','learn',{player})">{{ player+1 }}P {{ status.seats[player]?'다시 등록':'등록' }}</button><button v-if="status.seats[player]" class="clear-seat" @click="emit('command','clear',{player})">{{ player+1 }}P 등록 해제</button></div></div><div class="registration-tools"><button v-if="status.learning!==null" @click="emit('command','cancel')">재등록 취소</button><button :disabled="!status.seats.some(Boolean)&&status.learning===null" class="clear-seat" @click="emit('command','clearAll')">모두 등록 해제</button><button :disabled="!status.seats[0]||!status.seats[1]||status.learning!==null" @click="emit('command','swap')">1P ↔ 2P 바꾸기</button><button @click="emit('command','refresh')">연결 상태 새로고침</button></div><p class="registration-note" role="status">{{ status.note }}</p><small v-if="status.learning!==null">{{ status.learning+1 }}P가 사용할 키보드의 Space를 눌러 주세요. 취소하면 기존 등록을 유지합니다.</small><small>등록한 키보드는 이 맥에 기억해요. 재실행·재연결 시 자동 배정하며, 구분이 모호하면 다시 등록해 주세요. 분리되면 일시정지됩니다.</small></section></template>
<script setup lang="ts">
import type {KeyboardStatus} from '~/game/DualKeyboard'
const props=defineProps<{status:KeyboardStatus}>()
const emit=defineEmits<{command:[command:string,extra?:Record<string,unknown>]}>()
function selectDevice(player:number,event:Event){const device=(event.target as HTMLSelectElement).value;if(device)emit('command','assign',{player,device})}
const name=(player:number)=>props.status.devices.find(d=>d.id===props.status.seats[player])?.name||'미등록'
</script>
<style scoped>
.registration-seat select{max-width:100%;min-height:34px;border:1px solid #8bb5d0;border-radius:8px;background:white;color:#204c6b;font-size:11px;padding:5px}

.keyboard-registration{font:12px/1.6 Arial,'Apple SD Gothic Neo',sans-serif;color:#315977}.keyboard-registration h3{font-size:14px;margin:0 0 8px}.keyboard-registration>p{font-size:10px;margin:8px 0}.registration-seat{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 0;border-bottom:1px solid #9abed5}.registration-seat>span{min-width:0;flex:1}.registration-seat strong{font-size:13px}.registration-seat small{display:block;overflow-wrap:anywhere;font-size:10px}.registration-seat>div{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:5px;max-width:64%}.keyboard-registration button{background:linear-gradient(#c2ecff,#67aedb);border:2px solid white;border-radius:12px;color:#204c6b;font:bold 10px Arial;padding:7px 9px;min-height:34px;cursor:pointer;box-shadow:0 2px #7296ae}.keyboard-registration button:disabled{opacity:.4;cursor:default;filter:grayscale(.6)}.keyboard-registration button.clear-seat{background:linear-gradient(#fff3ed,#f4cfbf);color:#944832}.registration-tools{display:flex;flex-wrap:wrap;gap:7px;margin:10px 0}.keyboard-registration>small{display:block;font-size:9px;line-height:1.7;margin-top:9px}.keyboard-registration .registration-note{background:#ffffff88;border:1px solid #aac9dc;border-radius:5px;padding:8px;color:#315a79;font-size:10px}.keyboard-registration button:focus-visible{outline:3px solid #f4c63e;outline-offset:2px}
</style>
